-- V14 (The Visual Renaissance): the art pipeline's output is sound. Every asset the game can build has its data, its
-- groups are within EditableMesh's limits and the device budget, every layout points at real assets with clean
-- transforms, replacement art never brings collision of its own (the collision contract), and the Hero Skiff keeps
-- V10's skiff landmarks. (Generated by art/blender/scripts/lgexport.py: a failure here means re-export or fix a build
-- script, never hand-edit the generated files.)
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local StarterPlayer = game:GetService("StarterPlayer")

local Config = require(ReplicatedStorage:WaitForChild("LootGoblins").Config)
local Client = StarterPlayer:WaitForChild("StarterPlayerScripts"):WaitForChild("LootGoblinsClient")
local Art = Client:WaitForChild("Art14")
local Manifest = require(Art.Manifest)

local TINTS = { hull = true, stripe = true, trim = true, mast = true, sail = true, sailStripe = true }

local function layouts()
	local out = {}
	for _, module in ipairs(Art.Layouts:GetChildren()) do
		out[module.Name] = require(module)
	end
	return out
end

local function orthonormal(cf)
	local r = Vector3.new(cf[4], cf[7], cf[10])
	local u = Vector3.new(cf[5], cf[8], cf[11])
	local b = Vector3.new(cf[6], cf[9], cf[12])
	return math.abs(r.Magnitude - 1) < 0.01
		and math.abs(u.Magnitude - 1) < 0.01
		and math.abs(b.Magnitude - 1) < 0.01
		and math.abs(r:Dot(u)) < 0.01
		and math.abs(r:Dot(b)) < 0.01
end

return function(t)
	t.test("Config.ART: a V14 switch, a compare key and a budget per set", function()
		t.ok(type(Config.ART) == "table", "Config.ART")
		t.ok(type(Config.ART.V14) == "boolean", "V14 is a switch")
		t.ok(Enum.KeyCode[Config.ART.COMPARE_KEY] ~= nil, "a real key")
		for _, set in ipairs({ "Harbor", "Pebble", "Skiff" }) do
			t.ok(type(Config.ART.BUDGET[set]) == "number", "a vertex budget for " .. set)
		end
	end)

	t.test("every asset's groups are buildable: data present, sizes sane, within EditableMesh's limits", function()
		local count = 0
		for id, info in pairs(Manifest) do
			count += 1
			t.ok(#info.groups >= 1, id .. " has groups")
			local folder = Art.Meshes:FindFirstChild(id)
			for index, group in ipairs(info.groups) do
				t.ok(Enum.Material[group.material] ~= nil, id .. ": a Roblox material")
				t.ok(group.tint == nil or TINTS[group.tint], id .. ": a known paint role")
				t.ok(#group.offset == 3 and #group.size == 3, id .. ": offset and size")
				if not group.assetId then
					local module = folder and folder:FindFirstChild(tostring(index))
					t.ok(module ~= nil, id .. " group " .. index .. " has its data")
					local data = require(module)
					t.eq(#data.p % 3, 0, id .. " positions")
					t.eq(#data.f % 9, 0, id .. " triangles")
					t.ok(#data.p / 3 <= 60000 and #data.f / 9 <= 20000, id .. " within EditableMesh's limits")
					local np, nn, nc = #data.p / 3, #data.n / 3, #data.c / 3
					for i = 1, #data.f, 9 do
						for k = 0, 2 do
							t.ok(data.f[i + k] >= 1 and data.f[i + k] <= np, id .. " position index")
							t.ok(data.f[i + 3 + k] >= 1 and data.f[i + 3 + k] <= nn, id .. " normal index")
							t.ok(data.f[i + 6 + k] >= 1 and data.f[i + 6 + k] <= nc, id .. " colour index")
						end
					end
					-- positions are centred on the group: inside its half size (+ rounding)
					for i = 1, #data.p, 3 do
						for axis = 0, 2 do
							t.ok(
								math.abs(data.p[i + axis]) <= group.size[axis + 1] / 2 + 0.02,
								id .. " inside its size"
							)
						end
					end
				end
			end
		end
		t.ok(count >= 40, "the V14 set is exported (" .. count .. " assets)")
	end)

	t.test("generated sources stay under Roblox's 200,000-character script limit (Rojo's sync sets them)", function()
		local ok = pcall(function()
			return Art.Manifest.Source
		end)
		if not ok then
			return -- Source is not readable from this context; lgexport.py asserts the same limit when it writes
		end
		for _, folder in ipairs(Art.Meshes:GetChildren()) do
			for _, module in ipairs(folder:GetChildren()) do
				t.ok(#module.Source < 200000, folder.Name .. "/" .. module.Name .. " is under the limit")
			end
		end
	end)

	t.test("layouts point at real assets, with clean transforms; their hides and solids are well formed", function()
		for set, layout in pairs(layouts()) do
			t.ok(#layout.anchor == 3, set .. " anchor")
			local used = {}
			for _, item in ipairs(layout.items) do
				t.ok(Manifest[item.asset] ~= nil, set .. ": " .. item.asset .. " is in the manifest")
				t.eq(#item.cf, 12, set .. " cframe")
				t.ok(orthonormal(item.cf), set .. ": " .. item.asset .. " has a clean rotation")
				for _, s in ipairs(item.scale) do
					t.ok(s > 0.2 and s < 5, set .. ": a sane scale")
				end
				used[item.asset] = true
			end
			for _, hide in ipairs(layout.hides) do
				t.ok(#hide.names > 0, set .. " hide names")
				t.ok(hide.asset == nil or used[hide.asset], set .. ": a hide's replacement is placed")
				t.ok(hide.size[1] > 0 and hide.size[2] > 0 and hide.size[3] > 0, set .. " hide box")
			end
			for _, solid in ipairs(layout.solids) do
				t.ok(orthonormal(solid.cf), set .. " solid rotation")
			end
		end
	end)

	t.test("the collision contract: art that replaces V10/V13 brings no collision of its own", function()
		for set, layout in pairs(layouts()) do
			for _, hide in ipairs(layout.hides) do
				if hide.asset then
					local info = Manifest[hide.asset]
					t.ok(
						info.solids == nil or #info.solids == 0,
						set .. ": " .. hide.asset .. " (a replacement) is not solid"
					)
				end
			end
		end
		t.ok(Manifest.SK_HeroSkiff.solids == nil, "the Hero Skiff is never solid")
	end)

	t.test("each set fits its device budget (vertices built while its zone is near)", function()
		local sets = {}
		for set, layout in pairs(layouts()) do
			local seen, verts = {}, 0
			for _, item in ipairs(layout.items) do
				if not seen[item.asset] then
					seen[item.asset] = true
					verts += Manifest[item.asset].verts
				end
			end
			sets[set] = verts
			t.ok(verts <= Config.ART.BUDGET[set], set .. ": " .. verts .. " vertices within " .. Config.ART.BUDGET[set])
		end
		t.ok(Manifest.SK_HeroSkiff.verts <= Config.ART.BUDGET.Skiff, "the Hero Skiff within its budget")
		-- the biggest zone and the skiff must fit together (a skiff can sail into the Port)
		local biggest = 0
		for _, verts in pairs(sets) do
			biggest = math.max(biggest, verts)
		end
		t.ok(biggest + Manifest.SK_HeroSkiff.verts <= 36000, "the busiest moment fits the budget measured in Studio")
	end)

	t.test("the Hero Skiff keeps V10's skiff landmarks and takes every paint role", function()
		local info = Manifest.SK_HeroSkiff
		t.ok(info ~= nil, "exported")
		local roles = {}
		for _, group in ipairs(info.groups) do
			if group.tint then
				roles[group.tint] = true
			end
		end
		for role in pairs(TINTS) do
			t.ok(roles[role], "paint role " .. role)
		end
		local skiff = Config.BOAT_TYPES.skiff.size
		t.ok(info.size[1] <= skiff.X + 1.5, "about as wide as the hull part (" .. info.size[1] .. ")")
		t.ok(info.size[3] <= skiff.Z + 7, "about as long (the stem reaches past the bow skid) (" .. info.size[3] .. ")")
	end)
end
